sheet.css:
.pk{--glass:rgba(255,255,255,.20);--glass2:rgba(255,255,255,.12);--edge:rgba(255,255,255,.30);
  --r:16px;--sh:0 4px 30px rgba(0,0,0,.1);
  background:linear-gradient(135deg,#7b2ff7,#f107a3 55%,#ff6a3d);
  color:#fff;font:500 15px/1.5 ui-sans-serif,system-ui,sans-serif}
[data-theme=dark].pk,[data-theme=dark] .pk{--glass:rgba(255,255,255,.08);--edge:rgba(255,255,255,.22);
  background:linear-gradient(135deg,#2b0b57,#5a0540 55%,#6b2410)}
.stage.pk{background:linear-gradient(135deg,#7b2ff7,#f107a3 55%,#ff6a3d)}

.g{background:var(--glass);border:1px solid var(--edge);border-radius:var(--r);
  box-shadow:var(--sh);backdrop-filter:blur(16px) saturate(140%);
  -webkit-backdrop-filter:blur(16px) saturate(140%);padding:22px}
.g.sub{background:var(--glass2);backdrop-filter:blur(5px);-webkit-backdrop-filter:blur(5px)}
.g.thick{backdrop-filter:blur(24px) saturate(160%);-webkit-backdrop-filter:blur(24px) saturate(160%)}
.g.solid{background:rgba(30,10,50,.86);backdrop-filter:none;-webkit-backdrop-filter:none}
.scrim{background:linear-gradient(rgba(0,0,0,.45),rgba(0,0,0,.15));border-radius:12px;padding:14px 16px}

.pk-btn{font:600 15px/1 inherit;background:var(--glass);color:#fff;border:1px solid var(--edge);
  border-radius:12px;padding:12px 18px;cursor:pointer;backdrop-filter:blur(12px) saturate(140%);
  -webkit-backdrop-filter:blur(12px) saturate(140%);transition:background .16s}
.pk-btn:hover{background:rgba(255,255,255,.30)}
.pk-btn:focus-visible{outline:3px solid #fff;outline-offset:3px;box-shadow:0 0 0 6px rgba(0,0,0,.55)}
.pk-btn.pri{background:rgba(255,255,255,.92);color:#3b0764;border-color:transparent;
  backdrop-filter:none;-webkit-backdrop-filter:none}
.pk-btn[disabled]{opacity:.45;cursor:not-allowed}
.f-hover{background:rgba(255,255,255,.30)!important}
.f-focus{outline:3px solid #fff;outline-offset:3px;box-shadow:0 0 0 6px rgba(0,0,0,.55)}

.pk-field{width:100%;background:rgba(255,255,255,.34);color:#1a0b2e;border:1px solid var(--edge);
  border-radius:12px;padding:11px 14px;font:500 16px/1.2 inherit}
.pk-field::placeholder{color:#5b4272}
.pk-field:focus-visible{outline:3px solid #fff;outline-offset:3px}
.pk-label{display:block;font-weight:600;margin-bottom:6px;font-size:14px}
.pk-err{margin-top:8px;font-size:14px;font-weight:600;background:rgba(0,0,0,.5);
  border-radius:9px;padding:7px 10px;display:inline-block}

.pk-nav{display:flex;align-items:center;gap:10px}
.pk-nav .brand{font-weight:700;margin-right:10px}
.pk-nav a{color:#fff;text-decoration:none;font-size:14px;font-weight:600;padding:7px 11px;border-radius:9px}
.pk-nav a[aria-current]{background:rgba(255,255,255,.28)}
.pk-nav .sp{flex:1}

table.pk-t{width:100%;border-collapse:collapse;font-size:14px}
table.pk-t th{text-align:left;font-size:12px;letter-spacing:.06em;text-transform:uppercase;
  padding:0 0 10px;opacity:.85}
table.pk-t td{padding:10px 0;border-top:1px solid rgba(255,255,255,.22)}

.pk-scrim{background:rgba(0,0,0,.35);border-radius:var(--r);padding:34px 18px;display:flex;justify-content:center}
.pk-empty{border:1px dashed var(--edge);border-radius:var(--r);padding:24px;text-align:center;
  background:rgba(30,10,50,.55)}
.pk-skel{height:12px;background:rgba(255,255,255,.22);border-radius:6px;margin-bottom:9px}
.swatch{border:1px solid rgba(0,0,0,.15);border-radius:8px;height:54px}

page.css:
/* sheet.css gives .pk its own gradient so the MODULE SHEET has a backdrop.
   On the page that same rule paints a static copy on top of the fixed .bg and
   hides the parallax entirely. main/footer must be transparent here. */
main.pk, footer.pk{background:none}
/* The backdrop is not decoration — it is the thing glass exists to reveal.
   It sits BEHIND everything and is the only element that parallaxes. */
body{background:#1a0533;color:#fff;font:500 16px/1.55 ui-sans-serif,system-ui,sans-serif}
.bg{position:fixed;inset:-12% 0;z-index:-1;
  background:
    radial-gradient(60% 55% at 18% 22%, #7b2ff7 0%, transparent 62%),
    radial-gradient(55% 50% at 82% 30%, #f107a3 0%, transparent 60%),
    radial-gradient(70% 60% at 50% 92%, #ff6a3d 0%, transparent 65%),
    linear-gradient(160deg,#2b0b57,#4a0a3d 60%,#5c1f10)}
h1,h2,h3{margin:0;font-weight:700;letter-spacing:-.02em;line-height:1.05}
p{margin:0}
.s{padding-block:clamp(56px,9vw,120px)}
.kicker{font:700 12px/1 ui-monospace,monospace;letter-spacing:.16em;text-transform:uppercase;
  opacity:.85;margin-bottom:16px}
.btn{display:inline-block;text-decoration:none;font:600 16px/1 inherit;
  background:rgba(255,255,255,.92);color:#3b0764;border:1px solid transparent;border-radius:12px;
  padding:14px 22px;cursor:pointer;transition:background .16s}
.btn:hover{background:#fff}
.btn:focus-visible{outline:3px solid #fff;outline-offset:3px;box-shadow:0 0 0 6px rgba(0,0,0,.55)}
/* No backdrop-filter here. This button sits INSIDE .g.plate, and glass nested
   inside glass is a pack ban - the second blur has nothing new to refract and
   costs a second full-frame pass. Alpha carries the panel instead, which is
   the first mitigation a11y.contrastProblem names. */
.btn.ghost{background:rgba(255,255,255,.26);color:#fff;border-color:rgba(255,255,255,.44)}
.btn.ghost:hover{background:rgba(255,255,255,.30)}
nav.top{display:flex;align-items:center;gap:8px;padding:12px 16px}
nav.top .brand{font-weight:700;margin-right:14px}
nav.top a:not(.btn){color:#fff;text-decoration:none;font-weight:600;font-size:15px;
  padding:8px 12px;border-radius:10px}
/* :not(.btn) matters — nav.top a is (0,1,1) and was overriding .btn's own colour,
   which rendered the primary nav button as white text on a white pill. */
nav.top a[aria-current]{background:rgba(255,255,255,.26)}
nav.top .sp{flex:1}
.plate{max-width:640px}
.stat{display:flex;gap:28px;flex-wrap:wrap;margin-top:22px}
.stat b{display:block;font-size:30px;line-height:1}
.stat span{font-size:13px;opacity:.85}
.solidnote{background:rgba(20,5,40,.72);border:1px solid rgba(255,255,255,.22);border-radius:16px;
  padding:20px}
table.t{width:100%;border-collapse:collapse;font-size:15px}
table.t th{text-align:left;font-size:12px;letter-spacing:.06em;text-transform:uppercase;
  padding:0 0 10px;opacity:.85}
table.t td{padding:11px 0;border-top:1px solid rgba(255,255,255,.22)}
